159	    },
160	    /// Drop expired memories; optionally forgotten, superseded or unused ones.
161	    Prune {
162	        #[arg(long)]
163	        forgotten: bool,
164	        #[arg(long)]
165	        superseded: bool,
166	        /// Forget unpinned memories of importance 1-2 never recalled in this many days.
167	        #[arg(long, value_name = "DAYS")]
168	        unused: Option<u32>,
169	        #[arg(long)]
170	        dry_run: bool,
171	    },
172	}
